mapper.select:
select ${param.recordId} as record_id, tab_all.period_code, tab_all.currency_type,tab_all.org_id,tab_all.account_code , tab_all.contract_code ,tab_all.client_code , case when account.debit_credit_type = 'DR' then COALESCE(tab_all.month_end_debit_balance,0) - COALESCE(tab_all.month_end_credit_balance,0) when account.debit_credit_type = 'CR' then COALESCE(tab_all.month_end_credit_balance,0) - COALESCE(tab_all.month_end_debit_balance,0) else 0 end account_remain_balance, tab_all.detail_remain_balance, case when COALESCE(case when account.debit_credit_type = 'DR' then COALESCE(tab_all.month_end_debit_balance,0) - COALESCE(tab_all.month_end_credit_balance,0) when account.debit_credit_type = 'CR' then COALESCE(tab_all.month_end_credit_balance,0) - COALESCE(tab_all.month_end_debit_balance,0) else 0 end,0) = COALESCE(tab_all.detail_remain_balance,0) then '0' else '1' end diff_flag, COALESCE(case when account.debit_credit_type = 'DR' then COALESCE(tab_all.month_end_debit_balance,0) - COALESCE(tab_all.month_end_credit_balance,0) when account.debit_credit_type = 'CR' then COALESCE(tab_all.month_end_credit_balance,0) - COALESCE(tab_all.month_end_debit_balance,0) else 0 end,0)-COALESCE(tab_all.detail_remain_balance,0) as diff_balance, ${param.delFlag}, ${param.createBy}, now(), ${param.updateBy}, now() from (
select eaab.period_code,eaab.currency_code currency_type,eaab.org_id,eaab.account_code , eaab.contract_code ,eaab.client_code ,eaab.month_end_debit_balance , eaab.month_end_credit_balance,ecb.${item.queryField} detail_remain_balance from eg_account_assist_balance eaab join eg_check_account_detail_contract_balance ecb on eaab.period_code = ecb.period_code and eaab.org_id = ecb.org_id and eaab.contract_code = ecb.contract_code and eaab.client_code = ecb.client_code where eaab.period_code = #{param.periodCode} and eaab.account_code = #{item.accountCode} and eaab.del_flag = '0' and ecb.del_flag = '0'
) tab_all join (select distinct ea.account_code ,ea.debit_credit_type from eg_account ea) account on tab_all.account_code = account.account_code
